import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.ParserConfigurationException;
import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.Node;
import org.w3c.dom.NodeList;
import java.io.ByteArrayInputStream;
import java.io.IOException;

public class XmlParser {
    public static void main(String[] args) throws ParserConfigurationException, IOException {
        String xmlString = "<root><person><name>John Doe</name><age>30</age></person></root>";

        // Create a DocumentBuilderFactory instance
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();

        // Parse the XML string into a Document object
        Document document = factory.newDocumentBuilder().parse(new ByteArrayInputStream(xmlString.getBytes()));

        // Get the root element
        Element root = document.getDocumentElement();

        // Iterate over the elements in the root node
        NodeList nodeList = root.getChildNodes();
        for (int i = 0; i < nodeList.getLength(); i++) {
            Node node = nodeList.item(i);
            if (node.getNodeType() == Node.ELEMENT_NODE) {
                Element element = (Element) node;
                System.out.println("Element: " + element.getTagName());
                // Iterate over the child nodes of the current element
                NodeList childNodeList = element.getChildNodes();
                for (int j = 0; j < childNodeList.getLength(); j++) {
                    Node childNode = childNodeList.item(j);
                    if (childNode.getNodeType() == Node.ELEMENT_NODE) {
                        Element childElement = (Element) childNode;
                        System.out.println("Child element: " + childElement.getTagName());
                    }
                }
            }
        }
    }
}
